import { render } from "@testing-library/react";

import { StrategyArtBand, StrategyArtPlate } from "../strategy-art";
import { StatusTape, StrategyCard } from "../strategy-card";
import { strategiesWithArt, strategyArt } from "~/@/lib/strategies/art";
import { STRATEGY_SLUGS } from "~/@/lib/strategies/registry";

// The manifest is generated by the bake script; this is the one the tests
// see: one strategy with art, the rest without.
jest.mock("~/@/lib/strategies/art.generated", () => ({
  STRATEGY_ART: {
    "zanger-breakout": { hash: "a1b2c3" },
    "minervini-trend-template": { hash: "" },
  },
}));

describe("strategyArt", () => {
  it("builds the three URLs, each carrying the content hash", () => {
    expect(strategyArt("zanger-breakout")).toEqual({
      light: "/picks-art/zanger-breakout.light.avif?v=a1b2c3",
      dark: "/picks-art/zanger-breakout.dark.avif?v=a1b2c3",
      og: "/picks-art/og/zanger-breakout.jpg?v=a1b2c3",
      hash: "a1b2c3",
    });
  });

  it("is null for a strategy without baked art, an empty hash, or a slug off the registry", () => {
    expect(strategyArt("canslim")).toBeNull();
    expect(strategyArt("minervini-trend-template")).toBeNull();
    expect(strategyArt("toString")).toBeNull();
    expect(strategiesWithArt()).toEqual(["zanger-breakout"]);
  });

  it("only ever names registry strategies (the bake script keys the manifest by slug)", () => {
    for (const slug of strategiesWithArt()) {
      expect(STRATEGY_SLUGS).toContain(slug);
    }
  });
});

describe("StrategyArtBand and StrategyArtPlate", () => {
  it("render nothing at all for a strategy without art", () => {
    const { container } = render(
      <>
        <StrategyArtBand slug="canslim" />
        <StrategyArtPlate slug="canslim" />
      </>,
    );
    expect(container.innerHTML).toBe("");
  });

  it("draw the band through .banner-art with both theme URLs, under a scrim, decoratively", () => {
    const { container } = render(<StrategyArtBand slug="zanger-breakout" />);
    const band = container.querySelector('[data-strategy-art="band"]')!;
    expect(band).toHaveAttribute("aria-hidden", "true");
    const art = band.querySelector(".banner-art") as HTMLElement;
    expect(art.style.getPropertyValue("--banner-light")).toBe(
      "url('/picks-art/zanger-breakout.light.avif?v=a1b2c3')",
    );
    expect(art.style.getPropertyValue("--banner-dark")).toBe(
      "url('/picks-art/zanger-breakout.dark.avif?v=a1b2c3')",
    );
    // No <img>: one fetch, chosen by the active theme in CSS.
    expect(band.querySelector("img")).toBeNull();
    expect(band.querySelectorAll(".bg-gradient-to-r, .bg-gradient-to-t").length).toBe(2);
    expect(band.textContent).toBe("");
  });

  it("draws the plate as a bordered 3:2 tile", () => {
    const { container } = render(<StrategyArtPlate slug="zanger-breakout" />);
    const plate = container.querySelector('[data-strategy-art="plate"]')!;
    expect(plate).toHaveAttribute("aria-hidden", "true");
    expect(plate.className).toContain("banner-art");
    expect(plate.className).toContain("aspect-[3/2]");
  });
});

const COUNTS = {
  triggered: { count: 2, atLeast: false },
  setup: { count: 3, atLeast: false },
  watch: { count: 5, atLeast: true },
};

describe("StatusTape", () => {
  it("divides one band in proportion to the statuses, in ladder order", () => {
    const { container } = render(<StatusTape counts={COUNTS} ranked={10} />);
    const tape = container.querySelector("[data-status-tape]")!;
    expect(tape).toHaveAttribute("aria-hidden", "true");
    const segments = [...tape.querySelectorAll("[data-tape-segment]")] as HTMLElement[];
    expect(segments.map((s) => s.dataset.tapeSegment)).toEqual(["triggered", "setup", "watch"]);
    expect(segments.map((s) => s.style.flexGrow)).toEqual(["2", "3", "5"]);
    expect(segments[0]!.className).toContain("bg-primary");
    expect(segments[1]!.className).toContain("border-primary/70");
    expect(segments[2]!.className).toContain("bg-muted-foreground/30");
  });

  it("leaves out an empty status and draws nothing for an empty list", () => {
    const { container } = render(
      <StatusTape counts={{ ...COUNTS, triggered: { count: 0, atLeast: false } }} ranked={8} />,
    );
    expect(container.querySelectorAll("[data-tape-segment]")).toHaveLength(2);
    const empty = render(
      <StatusTape
        counts={{
          triggered: { count: 0, atLeast: false },
          setup: { count: 0, atLeast: false },
          watch: { count: 0, atLeast: false },
        }}
        ranked={0}
      />,
    );
    expect(empty.container.innerHTML).toBe("");
  });
});

describe("StrategyCard with art", () => {
  const props = {
    name: "Zanger Breakout",
    author: "Dan Zanger",
    tagline: "Breakouts.",
    counts: COUNTS,
    ranked: 10,
    leaders: [],
  };

  it("adds the plate column only for a strategy with baked art", () => {
    const withArt = render(<StrategyCard slug="zanger-breakout" {...props} />);
    const row = withArt.container.querySelector("article")!;
    expect(row).toHaveAttribute("data-strategy-art-row");
    expect(row.querySelector('[data-strategy-art="plate"]')).not.toBeNull();
    expect(row.className).toContain("md:grid-cols-[7.5rem_2.5rem_");
    expect(row.querySelector("[data-status-tape]")).not.toBeNull();

    const without = render(<StrategyCard slug="canslim" {...props} />);
    const plain = without.container.querySelector("article")!;
    expect(plain).not.toHaveAttribute("data-strategy-art-row");
    expect(plain.querySelector('[data-strategy-art="plate"]')).toBeNull();
    expect(plain.className).toContain("md:grid-cols-[2.5rem_");
  });
});
